// Writes the PrimeUI license key into a generated module that `provide-primeng.ts` imports.
//
// The key comes from the PRIMEUI_LICENSE environment variable (CI, Docker build) or, failing that,
// from apps/web/.env (local development). Neither the key nor the generated file is versioned.
// Without a key the app still works: PrimeNG shows its "Invalid PrimeUI License" notice.
//
// Runs before `start`, `build`, `watch` and `test` (see package.json).
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseEnv } from 'node:util';

const webRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const envFile = resolve(webRoot, '.env');
const target = resolve(webRoot, 'src/app/core/theme/primeng-license.generated.ts');

function readKey() {
  const fromEnv = process.env.PRIMEUI_LICENSE?.trim();
  if (fromEnv) return fromEnv;
  if (!existsSync(envFile)) return '';
  return parseEnv(readFileSync(envFile, 'utf8')).PRIMEUI_LICENSE?.trim() ?? '';
}

const key = readKey();
const content = `// Generated by scripts/write-license.mjs. Do not edit and do not commit.
export const PRIMEUI_LICENSE = ${JSON.stringify(key)};
`;

// Leave the file alone when nothing changed, so a running dev server does not rebuild.
if (!existsSync(target) || readFileSync(target, 'utf8') !== content) writeFileSync(target, content);

if (!key) {
  console.warn(
    '[license] PRIMEUI_LICENSE is not set: PrimeNG will show the "Invalid PrimeUI License" notice. ' +
      'See docs/DEVELOPMENT.md.',
  );
}
